compile.workshop:
variables {
    global:
        0: a
}

rule ("pass after skip") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        "pass"
        disabled Abort;
        Set Global Variable(a, 1);
        Set Global Variable(a, 2);
    }
}

rule ("pass after keyword skip") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(1);
        If(Compare(Global.a, ==, 1));
            "pass"
            disabled Abort;
        End;
        Set Global Variable(a, 2);
    }
}

rule ("pass after skip if zero") {
    event {
        Ongoing - Global;
    }
    actions {
        "pass"
        disabled Abort;
        "pass"
        disabled Abort;
        Set Global Variable(a, 1);
    }
}

